#include<algorithm>
using namespace std;

float g[110][110], dp[110][110];

int main(){

    int n,m;

    while(scanf("%d%d",&n,&m)&&(n||m)){

        for(int i=0;i<n;i++)

            for(int j=0;j<n;j++)

                scanf("%f",&g[i][j]);

        fill(dp[0],dp[0]+110*110,-1);

        for(int i=0;i<n;i++)

            dp[1][i]=1.0;



        for(int i=2;i<=m;i++)

            for(int j=0;j<n;j++)

                for(int k=0;k<n;k++)

                    dp[i][j] = max(dp[i][j],dp[i-1][k]*g[k][j]);

        float ans = -1;

        for(int i=0;i<n;i++)

            ans = max(ans,dp[m][i]);

        printf("%.2f\n",ans);

    }

}

